package dev.eugheist.ttmodern;
final class FlightDisabledAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT flight config: "+label);}
 static void run(net.neoforged.neoforge.event.server.ServerStartedEvent event){check(!TinkererConfig.flightEnabled(),"actual common configuration loaded false");var level=event.getServer().overworld();var p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(level);p.getInventory().clearContent();AwakenedArmorStatus.set(p,true);p.getAbilities().instabuild=false;p.getAbilities().mayfly=false;p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST,new net.minecraft.world.item.ItemStack(AwakenedChest.ITEM.get()));AwakenedChest.update(p);check(!p.getAbilities().mayfly,"config disables actual chest flight");var wand=new net.minecraft.world.item.ItemStack(dev.eugheist.tc4modern.TC4Modern.GOLD_GREATWOOD_WAND.get());dev.eugheist.tc4modern.FociContent.setFocus(wand,new net.minecraft.world.item.ItemStack(ThaumicTinkererModern.FOCUS_FLIGHT.get()));dev.eugheist.tc4modern.WandData.add(wand,thaumcraft.api.aspects.Aspect.AIR,50,true);int before=dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.AIR);p.setDeltaMovement(0,0,0);p.fallDistance=10;ThaumicTinkererModern.FOCUS_FLIGHT.get().onFocusRightClick(wand,level,p);check(p.getDeltaMovement().lengthSqr()==0&&p.fallDistance==10&&dev.eugheist.tc4modern.WandData.get(wand,thaumcraft.api.aspects.Aspect.AIR)==before,"focus refuses flight without movement/reset/vis debit");p.getInventory().clearContent();AwakenedChest.update(p);System.out.println("TT FLIGHT CONFIG AUDIT: ALL PASS (actual enableFlight=false blocks chest and focus,no resource debit)");}
}
